func readReleaseChainV12Prerequisite() (releaseChainV5Prerequisite, error) {
	var result releaseChainV5Prerequisite
	for _, item := range []struct{ file, pin, semantic string }{
		{"release-chain-v12-high-prerequisite-20261013.json", releaseChainV12ReviewedPrerequisiteSHA, releaseChainV12PrerequisiteSemanticJSON},
		{"release-chain-v12-user-policy-amendment-20261013.json", releaseChainV12AuthoritySHA, releaseChainV12AuthoritySemanticJSON},
		{"release-chain-v11-user-expense-exception-20261013.json", releaseChainV11ExpenseExceptionSHA, releaseChainV11ExpenseExceptionSemanticJSON},
	} {
		raw, err := readReleaseChainV5Artifact(highHistoryPath(item.file), item.pin)
		if err != nil || !releaseChainV7ExactSemantic(raw, item.semantic) {
			return result, errNativeFixtureDenied
		}
	}
	h, err := readReleaseChainV12ActualHistory()
	if err != nil {
		return result, errNativeFixtureDenied
	}
	result, err = readReleaseChainV5Prerequisite()
	if err != nil {
		return result, errNativeFixtureDenied
	}
	result.Baseline, result.ChainHistorySHA = h.NativeAttempts, h.BaselineSHA256
	return result, nil
}
func newReleaseChainV12Window(ctx context.Context, pool *pgxpool.Pool) (*releaseChainV5Window, error) {
	p, err := readReleaseChainV12Prerequisite()
	if err != nil {
		return nil, errNativeFixtureDenied
	}
	deadline, err := time.Parse(time.RFC3339, os.Getenv("BUTLER_SCENARIO_CHAIN_V12_HIGH_DEADLINE"))
	if err != nil {
		return nil, errNativeFixtureDenied
	}
	return createReleaseChainHighWindowWithPolicy(ctx, pool, releaseChainV12ReviewedPrerequisiteSHA, p.ChainHistorySHA, 575, "fixture_chain_v12_high", deadline, 120, true, releaseChainV9Policy(), true)
}
